    put("110851", "在競賽中間附近若位於隊列中段速度稍微上升若是一哩競賽則使效果及時間增加")
    put("110861", "在剩餘300m處若位於隊列前方速度會稍微上升，若發動技能時位居領先或距離最前頭2身距以內則會大幅上升＜作戰．前列＞")
    put("110871", "在競賽中間附近若位於隊列前方速度會上升，當智力數值十二分強大時則會大幅上升＜短距離＞")
    put("110881", "在競賽中期一開始若追過對手短時間內大幅向前邁進若是中距離競賽則短時間內極大幅向前邁進＜作戰．居中＞")
    put("110891", "在競賽中間附近位於隊列中段時使速度在較長時間內稍微持續上升並回復持久力若是不到3000m的競賽則不回復持久力使速度在較長時間內持續上升＜長距離＞")
    put("110911", "在競賽後半的第3彎道若位於隊列中段速度會稍微上升若是2000m的競賽且該處是上坡則效果及時間增加")
    put("110931", "在競賽中期若位於隊列中段與對手競爭在最後衝刺階段速度會上升並在短距離競賽發動技能時若位居第3以內則會再略微向前邁進")
    put("110981", "在競賽後期若位於隊列前方當距離終點尚遠時會向前邁進＜沙地＞")
    put("110991", "在競賽中間點使速度稍微上升在沙地競賽發動技能時若不在第3彎道則會再使速度略微上升")
    put("111041", "到競賽後半為止若能維持在隊列前方會使速度於長時間內稍微持續上升若「強勢領頭」有發動時則效果變為大幅回復持久力＜中距離＞")
    put("111051", "在後期的最後直線若位列第2之後會使速度上升，在競賽中期若剛好發動了7次或13次技能則會極大幅上升")
    put("111061", "在競賽中期準備追過對手時於極短時間內稍微向前邁進，之後在後期的最後彎道後半若位於隊列中段之後短時間內速度上升")
    put("111071", "接近後期的某處若位於隊列前方會使速度稍微持續上升且若位居第3以內則會再使加速力些微持續上升＜中距離＞")
    put("111091", "若是三后冠的賽道在後期的彎道於短時間內稍微向前邁進，且若該處是下坡則加速力會再略微上升")
    put("111101", "在最後衝刺階段短時間內速度大幅上升，若在中距離競賽則效果增加＜作戰．前列＞")
    put("120011", "在後期最後彎道若發動技能會因為聲援而使速度稍微上升若在中山賽場則會大幅上升")
    put("120031", "在競賽後半若位於隊列前方被對手逼近速度會在後期最後彎道後半之後上升且若是2400m～2500m的競賽則會再略微向前邁進")
    put("120041", "在競賽中期一開始若位於隊列前方準備追過對手或被逼近時，短時間內稍微向前邁進，當在一哩競賽時則短時間內大幅向前邁進")
    put("120071", "在最後彎道之後從隊列後方準備追過對手時，速度上升起跑時若有所延遲則大幅上升＜中距離/長距離＞")
    put("120111", "在競賽後半若位於隊列中段準備追過對手或被逼近時在剩餘400m處會使速度上升當在非主要距離競賽時則會大幅上升")
    put("120131", "在競賽後半若位於領先集團視剩餘持久力進行長距離衝刺使速度略微持續上升")
    put("120231", "在競賽中間點若位於隊列前方會使速度上升，若在長距離競賽前半的彎道有與對手發生競爭則會極大幅上升")
    put("120241", "在競賽中期之後若位於領先或第3以內準備追過對手時，會大幅回復持久力並稍微持續向前邁進")
    put("120301", "在後期的最後彎道若位於隊列前方會使速度上升，在京都賽場的長距離競賽則會極大幅上升")
    put("120311", "接近競賽中期時若位於隊列前方速度會略微上升，若是中距離競賽則之後在中期的直線速度稍微上升")
    put("120321", "在後期的最後彎道之後若位於隊列前方短時間內會使速度大幅上升在中距離競賽則使效果變為短時間內大幅向前邁進")
    put("120351", "在競賽中期若從隊列中段追過對手則在第3彎道短時間內會使速度上升在2400m的競賽且獲得高支持度時則持續上升")
    put("120371", "在最後彎道位於隊列中段會向前邁進若在東京賽場的競賽則會大幅向前邁進＜中距離＞")
    put("120401", "在競賽中間附近若位於隊列中段極短時間內速度稍微上升之後若在後期的彎道與對手競爭在剩餘350m處極短時間內速度大幅上升")
    put("120451", "在競賽中期的彎道若位於良好位置會回復持久力且在中距離或長距離競賽則會再使速度稍微持續上升")
    put("120461", "在競賽後半速度上升若沒有晚起跑且能維持在隊列前方則會極大幅上升＜沙地＞")
    put("120501", "在競賽後期的彎道若位於隊列後方當距離終點尚遠時短時間內向前邁進若在中山賽場的中距離競賽則效果增加且加速力些微上升")
    put("120601", "在後期的最後彎道之後若位於隊列中段之後短時間內會使速度大幅上升在中距離競賽則使效果變為短時間內大幅向前邁進")
